krpano.action:
copy(drag_x, mouse.stagex);
copy(drag_y, mouse.stagey);
copy(drag_layerx, layer[img_popup_photo].x);
copy(drag_layery, layer[img_popup_photo].y);
asyncloop(pressed,
    sub(dx, mouse.stagex, drag_x);
    sub(dy, mouse.stagey, drag_y);
    set(layer[img_popup_photo].x, add(drag_layerx, dx));
    set(layer[img_popup_photo].y, add(drag_layery, dy));
);

    showTextModal(
        "SISTER-CITY RELATIONSHIP BETWEEN THE CITY OF LEGAZPI AND AYUNTAMIENTO ZUMARRAGA",
        "Legazpi City established a Sister-City Relationship with Zumarraga, Spain, on October 21, 1975, to honor the birthplace of Adelantado Don Miguel Lopez de Legazpi, the city's namesake. The agreement, signed by Mayor Gregorio Imperial and Alcalde Don Cruz-Maria Uribezalgo Larranaga, promotes cooperation through the exchange of information on history, culture, tourism, literature, governance, and other shared interests. In February 2012, Mayor Geraldine Rosal and City Administrator Noel Rosal visited Zumarraga to strengthen ties and discuss tourism, investments, and business opportunities with local officials. The visit was sponsored by AECID, Spain's development agency, which has provided significant financial and technological assistance to Legazpi, including over PHP 100 million for the city's sanitary landfill project."
    );
